import React from 'react';

import Details from '../komponen/Details';


function Abouts(props) {

    return(
      <div>

        <div className="d-inline-block"
            onClick={(e) => props.click(props.item)}>
            <img className="g-card-image"
              src={props.item.img}
              alt={props.item.img} />
        </div>
        <div>
        { props.item.pilih &&
          <Details name={props.item.name}
                    sub={props.item.sub}
                     id={props.item.id}
           />
        }
        </div>
      </div>
    );

}

export default Abouts;



